{% assign prijskleur = '#00AD7C' %}
{% assign oude_prijskleur = '#CC2525' %}

<style>
  /* Huidige prijs */
  #shopify-section-{{ section.id }} .product__price:not(.product__price--compare),
  #shopify-section-{{ section.id }} .product__price:not(.product__price--compare) .money {
    color: {{ prijskleur }} !important;
    font-size: 30px !important;
    font-weight: 700 !important;
    line-height: 1.2 !important;
  }

  /* Oude prijs */
  #shopify-section-{{ section.id }} .product__price--compare,
  #shopify-section-{{ section.id }} .product__price--compare .money {
    color: {{ oude_prijskleur }} !important;
    font-size: 20px !important;
    font-weight: 400 !important;
    text-decoration: line-through !important;
  }

  #shopify-section-{{ section.id }} .product__price--compare {
    margin-right: 10px;
  }

  /* Actielabel met de bestaande korting */
  #shopify-section-{{ section.id }} .product__price-savings {
    display: inline-flex !important;
    align-items: center;
    vertical-align: middle;
    margin-left: 10px !important;
    padding: 5px 9px !important;
    background: {{ prijskleur }} !important;
    color: #fff !important;
    border: 0 !important;
    border-radius: 0 !important;
    font-family: inherit;
    font-size: 12px !important;
    font-weight: 600 !important;
    line-height: 1.2 !important;
    letter-spacing: .3px !important;
    text-transform: uppercase !important;
    white-space: nowrap;
  }

  #shopify-section-{{ section.id }} .product__price-savings::before,
  #shopify-section-{{ section.id }} .product__price-savings::after {
    content: none !important;
  }

  /* Verborgen houden wanneer er geen korting is */
  #shopify-section-{{ section.id }} .product__price-savings.hide,
  #shopify-section-{{ section.id }} .product__price-savings.hidden,
  #shopify-section-{{ section.id }} .product__price-savings[hidden],
  #shopify-section-{{ section.id }} .product__price-savings:empty {
    display: none !important;
  }

  @media (max-width: 749px) {
    #shopify-section-{{ section.id }} .product__price:not(.product__price--compare),
    #shopify-section-{{ section.id }} .product__price:not(.product__price--compare) .money {
      font-size: 26px !important;
    }

    #shopify-section-{{ section.id }} .product__price--compare,
    #shopify-section-{{ section.id }} .product__price--compare .money {
      font-size: 18px !important;
    }

    #shopify-section-{{ section.id }} .product__price--compare {
      margin-right: 6px;
    }

    #shopify-section-{{ section.id }} .product__price-savings {
      margin-left: 7px !important;
      padding: 5px 7px !important;
      font-size: 11px !important;
    }
  }
</style>

<script>
(() => {
  const section = document.getElementById(
    'shopify-section-{{ section.id }}'
  );

  if (!section) return;

  if (section.susansSavingsObserver) {
    section.susansSavingsObserver.disconnect();
  }

  const updateSavings = () => {
    section.querySelectorAll('.product__price-savings').forEach((label) => {
      const percentage = label.textContent.match(
        /(\d+(?:[.,]\d+)?)\s*%/
      );

      if (!percentage) return;

      const text = 'SAVE TODAY ' + percentage[1] + '%';

      if (label.textContent !== text) {
        label.textContent = text;
      }
    });
  };

  updateSavings();

  const observer = new MutationObserver(updateSavings);

  observer.observe(section, {
    childList: true,
    subtree: true,
    characterData: true
  });

  section.susansSavingsObserver = observer;
})();
</script>

{% assign photo_color_option = nil %}

{% for option in product.options_with_values %}
  {% assign normalized_name = option.name | downcase | strip %}
  {% if normalized_name contains 'color' or normalized_name contains 'colour' or normalized_name contains 'kleur' %}
    {% assign photo_color_option = option %}
    {% break %}
  {% endif %}
{% endfor %}

{% if photo_color_option %}
  {% assign photo_color_index = photo_color_option.position | minus: 1 %}

  <boutique-photo-colors hidden>
    {% for value in photo_color_option.values %}
      {% assign photo_color_name = value.name | default: value %}
      {% assign photo_color_image = nil %}

      {% for variant in product.variants %}
        {% if variant.options[photo_color_index] == photo_color_name %}
          {% if variant.featured_image %}
            {% assign photo_color_image = variant.featured_image %}
            {% break %}
          {% endif %}
        {% endif %}
      {% endfor %}

      <span
        data-color="{{ photo_color_name | escape }}"
        {% if photo_color_image %}
          data-photo="{{ photo_color_image | image_url: width: 240 | escape }}"
        {% endif %}
      ></span>
    {% endfor %}
  </boutique-photo-colors>

  <style>
    boutique-photo-colors {
      display: none !important;
    }

    /* Foto's: klein, wit binnenrandje en zwarte omlijning */
    label.boutique-photo-label {
      display: inline-block !important;
      box-sizing: border-box !important;

      width: 68px !important;
      min-width: 68px !important;
      max-width: 68px !important;
      height: 88px !important;
      min-height: 88px !important;

      margin: 3px 10px 10px 3px !important;
      padding: 3px !important;

      border: 1px solid #111 !important;
      border-radius: 3px !important;

      background-color: #fff !important;
      background-image: var(--boutique-color-photo) !important;
      background-position: center !important;
      background-size: cover !important;
      background-repeat: no-repeat !important;
      background-origin: content-box !important;
      background-clip: content-box !important;

      color: transparent !important;
      font-size: 0 !important;
      line-height: 0 !important;
      text-shadow: none !important;

      box-shadow: none !important;
      overflow: hidden !important;
      vertical-align: top !important;
      cursor: pointer;

      transition: box-shadow .15s ease;
    }

    /* Verberg de oorspronkelijke kleurbolletjes en tekst */
    label.boutique-photo-label > *,
    label.boutique-photo-label::before,
    label.boutique-photo-label::after {
      visibility: hidden !important;
    }

    /* Dikkere rand zonder verspringende foto's */
    label.boutique-photo-label:hover,
    label.boutique-photo-label.is-selected {
      border: 1px solid #111 !important;
      box-shadow: 0 0 0 2px #111 !important;
    }

    label.boutique-photo-label.is-disabled {
      opacity: .45;
      cursor: not-allowed;
    }

    /* Bestaande houders behouden hun werking */
    .variant-input:has(label.boutique-photo-label) {
      display: inline-block !important;
      width: auto !important;
      margin: 0 !important;
      padding: 0 !important;
      vertical-align: top !important;
    }

    /* Vervang de dubbele titel visueel door alleen COLOR */
    .boutique-color-heading {
      font-size: 0 !important;
      line-height: 0 !important;
    }

    .boutique-color-heading > * {
      display: none !important;
    }

    .boutique-color-heading::before {
      content: "COLOR";
      display: block;
      color: #111;
      font-size: 13px;
      line-height: 1.5;
      font-weight: 400;
      letter-spacing: 3px;
      margin-bottom: 10px;
    }

    .boutique-color-heading::after {
      display: none !important;
    }

    input:focus-visible + label.boutique-photo-label {
      outline: 2px solid #111 !important;
      outline-offset: 4px !important;
    }

    @media (max-width: 749px) {
      label.boutique-photo-label {
        width: 62px !important;
        min-width: 62px !important;
        max-width: 62px !important;
        height: 80px !important;
        min-height: 80px !important;
      }
    }
  </style>

  <script>
    if (!customElements.get('boutique-photo-colors')) {
      customElements.define(
        'boutique-photo-colors',
        class extends HTMLElement {
          connectedCallback() {
            this.scope = this.closest('.shopify-section');
            if (!this.scope) return;

            this.schedule = () => {
              cancelAnimationFrame(this.frame);
              this.frame = requestAnimationFrame(() => this.apply());
            };

            this.scope.addEventListener('change', this.schedule);

            this.observer = new MutationObserver(this.schedule);
            this.observer.observe(this.scope, {
              childList: true,
              subtree: true
            });

            this.schedule();
          }

          apply() {
            const entries = [...this.querySelectorAll('[data-color]')];
            if (!entries.length) return;

            const colors = new Set(
              entries.map(entry => entry.dataset.color)
            );

            const photos = new Map(
              entries
                .filter(entry => entry.dataset.photo)
                .map(entry => [
                  entry.dataset.color,
                  entry.dataset.photo
                ])
            );

            const groups = new Map();

            this.scope
              .querySelectorAll('input[type="radio"]')
              .forEach(input => {
                if (!input.name) return;

                if (!groups.has(input.name)) {
                  groups.set(input.name, []);
                }

                groups.get(input.name).push(input);
              });

            groups.forEach(inputs => {
              const matchesColors =
                inputs.every(input => colors.has(input.value)) &&
                [...colors].every(color =>
                  inputs.some(input => input.value === color)
                );

              if (!matchesColors) return;

              inputs.forEach(input => {
                const photo = photos.get(input.value);
                if (!photo) return;

                const label = [...(input.labels || [])].find(
                  item => this.scope.contains(item)
                );

                if (!label) return;

                label.classList.add('boutique-photo-label');
                label.classList.toggle('is-selected', input.checked);
                label.classList.toggle('is-disabled', input.disabled);

                label.style.setProperty(
                  '--boutique-color-photo',
                  'url("' + photo + '")'
                );

                input.setAttribute('aria-label', input.value);

                const wrapper = input.closest('.variant-wrapper');

                if (wrapper) {
                  const heading = wrapper.querySelector('.variant__label');

                  if (heading && !heading.contains(input)) {
                    heading.classList.add('boutique-color-heading');
                  }
                } else {
                  const fieldset = input.closest('fieldset');
                  const legend = fieldset?.querySelector('legend');

                  if (legend) {
                    legend.classList.add('boutique-color-heading');
                  }
                }
              });
            });
          }

          disconnectedCallback() {
            cancelAnimationFrame(this.frame);
            this.observer?.disconnect();
            this.scope?.removeEventListener('change', this.schedule);
          }
        }
      );
    }
  </script>
{% endif %}

{% assign variant = product.selected_or_first_available_variant %}

{% if variant.inventory_management != blank
  and variant.inventory_policy == 'deny'
  and variant.inventory_quantity > 0
  and variant.inventory_quantity <= 10
%}
  <div class="aspen-low-stock" role="status">
    <span class="aspen-low-stock__dot" aria-hidden="true"></span>
    <span>Only {{ variant.inventory_quantity }} left in stock</span>
  </div>
{% endif %}

<style>
  .aspen-low-stock {
    display: flex;
    align-items: center;
    gap: 12px;
    margin: 12px 0;
    color: #CC2525;
    font-family: inherit;
    font-size: 15px;
    font-weight: 400;
    line-height: 1.4;
  }

  .aspen-low-stock__dot {
    width: 12px;
    height: 12px;
    flex-shrink: 0;
    margin: 6px;
    border-radius: 50%;
    background: #CC2525;
    box-shadow: 0 0 0 6px #F1CCCC;
  }

  @media (max-width: 749px) {
    .aspen-low-stock {
      font-size: 14px;
      gap: 10px;
    }
  }
</style>
